--
-- Table structure for table `generals`
--

DROP TABLE IF EXISTS `generals`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `generals` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(100) DEFAULT NULL,
  `subtitle` varchar(200) DEFAULT NULL,
  `about` text DEFAULT NULL,
  `website` varchar(100) DEFAULT NULL,
  `logo` varchar(100) DEFAULT NULL,
  `favicon` varchar(100) DEFAULT NULL,
  `mobile` varchar(250) DEFAULT NULL,
  `email` varchar(250) DEFAULT NULL,
  `address_one` text DEFAULT NULL,
  `address_two` text DEFAULT NULL,
  `postal_address` varchar(191) DEFAULT NULL,
  `postal_code` varchar(10) DEFAULT NULL,
  `city` varchar(50) DEFAULT NULL,
  `state` varchar(50) DEFAULT NULL,
  `division` varchar(50) DEFAULT NULL,
  `country` varchar(50) DEFAULT NULL,
  `commingsoon_mode` tinyint(1) NOT NULL DEFAULT 0,
  `notification_status` tinyint(1) NOT NULL DEFAULT 0,
  `fb_pageId` varchar(100) DEFAULT NULL,
  `meta_keyword` text DEFAULT NULL,
  `meta_description` varchar(200) DEFAULT NULL,
  `meta_author` varchar(100) DEFAULT NULL,
  `meta_title` varchar(200) DEFAULT NULL,
  `script_head` longtext DEFAULT NULL,
  `script_body` longtext DEFAULT NULL,
  `custom_css` longtext DEFAULT NULL,
  `custom_js` longtext DEFAULT NULL,
  `copyright_text` text DEFAULT NULL,
  `inside_dhaka_shipping_charge` float(10,2) NOT NULL DEFAULT 0.00,
  `outside_metro_charge` float NOT NULL DEFAULT 0,
  `outside_metro_area` text DEFAULT NULL,
  `outside_dhaka_shipping_charge` float(10,2) NOT NULL DEFAULT 0.00,
  `minimum_shopping` float(10,2) NOT NULL DEFAULT 0.00,
  `mail_driver` varchar(100) DEFAULT NULL,
  `mail_host` varchar(100) DEFAULT NULL,
  `mail_port` varchar(100) DEFAULT NULL,
  `mail_username` varchar(100) DEFAULT NULL,
  `mail_password` varchar(100) DEFAULT NULL,
  `mail_encryption` varchar(100) DEFAULT NULL,
  `mail_from_name` varchar(100) DEFAULT NULL,
  `mail_from_address` varchar(100) DEFAULT NULL,
  `mail_status` tinyint(1) NOT NULL DEFAULT 0,
  `sms_username` varchar(50) DEFAULT NULL,
  `sms_password` varchar(50) DEFAULT NULL,
  `sms_senderid` varchar(50) DEFAULT NULL,
  `sms_url_masking` varchar(200) DEFAULT NULL,
  `sms_url_nonmasking` varchar(200) DEFAULT NULL,
  `sms_type` varchar(50) DEFAULT NULL,
  `sms_status` tinyint(1) NOT NULL DEFAULT 0,
  `admin_numbers` text DEFAULT NULL,
  `fb_app_id` varchar(100) DEFAULT NULL,
  `fb_app_secret` varchar(100) DEFAULT NULL,
  `fb_app_redirect_url` varchar(200) DEFAULT NULL,
  `tw_app_id` varchar(100) DEFAULT NULL,
  `tw_app_secret` varchar(100) DEFAULT NULL,
  `tw_app_redirect_url` varchar(200) DEFAULT NULL,
  `google_client_id` varchar(100) DEFAULT NULL,
  `google_client_secret` varchar(100) DEFAULT NULL,
  `google_client_redirect_url` varchar(200) DEFAULT NULL,
  `facebook_link` varchar(200) DEFAULT NULL,
  `twitter_link` varchar(200) DEFAULT NULL,
  `instagram_link` varchar(200) DEFAULT NULL,
  `linkedin_link` varchar(200) DEFAULT NULL,
  `pinterest_link` varchar(200) DEFAULT NULL,
  `youtube_link` varchar(200) DEFAULT NULL,
  `shipping_charge_type` tinyint(4) NOT NULL DEFAULT 0,
  `defult_shipping_charge` float(10,2) NOT NULL DEFAULT 0.00,
  `product_discount` int(11) NOT NULL DEFAULT 0,
  `tax` int(11) NOT NULL DEFAULT 0,
  `tax_status` tinyint(1) NOT NULL DEFAULT 0,
  `currency` varchar(10) DEFAULT NULL,
  `currency_decimal` int(11) NOT NULL DEFAULT 0 COMMENT '0=0,1=0.0,2=0.00',
  `currency_position` int(11) NOT NULL DEFAULT 0 COMMENT '0=left, 1=right',
  `seller_product_verify` tinyint(1) NOT NULL DEFAULT 0,
  `coupon_apply` tinyint(1) NOT NULL DEFAULT 0,
  `slider` int(11) DEFAULT NULL,
  `cus_reg_sms_customer` tinyint(1) NOT NULL DEFAULT 0,
  `cus_reg_sms_admin` tinyint(1) NOT NULL DEFAULT 0,
  `vendor_reg_sms_vendor` tinyint(1) NOT NULL DEFAULT 0,
  `vendor_reg_sms_admin` tinyint(1) NOT NULL DEFAULT 0,
  `order_place_sms_customer` tinyint(1) NOT NULL DEFAULT 0,
