DROP TABLE IF EXISTS `order_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `order_items` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint(20) DEFAULT NULL,
  `invoice` bigint(20) DEFAULT NULL,
  `user_id` int(11) DEFAULT NULL,
  `seller_id` int(11) DEFAULT NULL,
  `product_id` int(11) DEFAULT NULL,
  `product_name` varchar(250) DEFAULT NULL,
  `quantity` int(11) NOT NULL DEFAULT 0,
  `color` varchar(100) DEFAULT NULL,
  `size` varchar(100) DEFAULT NULL,
  `sku_id` text DEFAULT NULL,
  `sku_ids` text DEFAULT NULL,
  `price` float(10,2) NOT NULL DEFAULT 0.00,
  `total_coupon_discount` float(10,2) NOT NULL DEFAULT 0.00,
  `total_deal_discount` float(10,2) NOT NULL DEFAULT 0.00,
  `total_price` float(10,2) NOT NULL DEFAULT 0.00,
  `final_price` float(10,2) NOT NULL DEFAULT 0.00,
  `shipping_cost` float(10,2) NOT NULL DEFAULT 0.00,
  `total_weight` int(11) NOT NULL DEFAULT 0,
  `total_return` int(11) NOT NULL DEFAULT 0,
  `status` varchar(20) DEFAULT NULL COMMENT 'Pending, Confirmed, Runing, Cancel',
  `order_status` varchar(30) DEFAULT NULL,
  `customer_delivery_user` int(11) DEFAULT NULL,
  `pending_at` timestamp NULL DEFAULT NULL,
  `pending_by` int(11) DEFAULT NULL,
  `confirmed_at` timestamp NULL DEFAULT NULL,
  `confirmed_by` int(11) DEFAULT NULL,
  `cancelled_at` timestamp NULL DEFAULT NULL,
  `cancelled_by` int(11) DEFAULT NULL,
  `shipped_at` timestamp NULL DEFAULT NULL,
  `shipped_by` int(11) DEFAULT NULL,
  `delivered_at` timestamp NULL DEFAULT NULL,
  `delivered_by` int(11) DEFAULT NULL,
  `payment_status` varchar(20) DEFAULT 'unpaid',
  `return_cancel_at` timestamp NULL DEFAULT NULL,
  `return_cancel_by` int(11) DEFAULT NULL,
  `return_cancel_msg` text DEFAULT NULL,
  `addedby_id` int(11) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2597 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

