CREATE TABLE `order_return_items` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(11) DEFAULT NULL,
  `order_id` int(11) DEFAULT NULL,
  `order_item_id` int(11) DEFAULT NULL,
  `product_id` int(11) DEFAULT NULL,
  `seller_id` int(11) DEFAULT NULL,
  `sold_quantity` int(11) DEFAULT NULL,
  `return_quantity` int(11) DEFAULT NULL,
  `sold_price` float(10,2) NOT NULL DEFAULT 0.00,
  `return_price` float(10,2) NOT NULL DEFAULT 0.00,
  `finaly_return` float(10,2) NOT NULL DEFAULT 0.00,
  `vat` float(10,2) NOT NULL DEFAULT 0.00,
  `return_status` varchar(20) DEFAULT NULL,
  `reasion` varchar(100) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'pending',
  `return_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0=cancel, 1=return',
  `accepted` tinyint(1) NOT NULL DEFAULT 0,
  `search_key` text DEFAULT NULL,
  `pending_at` timestamp NULL DEFAULT NULL,
  `pending_by` int(11) DEFAULT NULL,
  `confirmed_at` timestamp NULL DEFAULT NULL,
  `confirmed_by` int(11) DEFAULT NULL,
  `delivered_at` timestamp NULL DEFAULT NULL,
  `delivered_by` int(11) DEFAULT NULL,
  `cancelled_at` timestamp NULL DEFAULT NULL,
  `cancelled_by` int(11) DEFAULT NULL,
  `addedby_id` int(11) DEFAULT NULL,
  `editedby_id` int(11) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
