  `company` varchar(100) DEFAULT NULL,
  `mobile` varchar(20) DEFAULT NULL,
  `email` varchar(50) DEFAULT NULL,
  `division` int(11) DEFAULT NULL,
  `district` int(11) DEFAULT NULL,
  `city` int(11) DEFAULT NULL,
  `city_name` varchar(100) DEFAULT NULL,
  `address` text DEFAULT NULL,
  `postal_code` text DEFAULT NULL,
  `shipping_address_status` tinyint(1) NOT NULL DEFAULT 0,
  `shipping_name` varchar(100) DEFAULT NULL,
  `shipping_last_name` varchar(100) DEFAULT NULL,
  `shipping_company` varchar(100) DEFAULT NULL,
  `shipping_mobile` varchar(20) DEFAULT NULL,
  `shipping_email` varchar(100) DEFAULT NULL,
  `shipping_division` int(11) DEFAULT NULL,
  `shipping_district` int(11) DEFAULT NULL,
  `shipping_city` int(11) DEFAULT NULL,
  `shipping_city_name` varchar(100) DEFAULT NULL,
  `shipping_postal_code` varchar(100) DEFAULT NULL,
