  `return_status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT 'pending, confirmed, on delivery, completed, cancel',
  `return_amount` float(10,2) NOT NULL DEFAULT 0.00,
  `payment_status` varchar(10) DEFAULT 'unpaid' COMMENT 'unpaid, partial, paid',
  `payment_method` varchar(50) DEFAULT NULL,
  `transection` varchar(100) DEFAULT NULL,
  `emi_status` tinyint(1) NOT NULL DEFAULT 0,
  `order_type` varchar(15) NOT NULL DEFAULT 'customer_order' COMMENT 'customer_order, pos_order, purchase_order, quotation_order',
  `total_price` float(10,2) NOT NULL DEFAULT 0.00,
  `total_items` int(11) NOT NULL DEFAULT 0,
  `total_qty` int(11) DEFAULT 0,
  `shipping_charge` float(10,2) NOT NULL DEFAULT 0.00,
  `tax` float(10,2) NOT NULL DEFAULT 0.00,
  `discount_type` varchar(20) DEFAULT NULL COMMENT 'Percantage, Flat',
  `discount` float(10,2) NOT NULL DEFAULT 0.00,
  `discount_price` float(10,2) NOT NULL DEFAULT 0.00,
  `coupon_discount` float(10,2) NOT NULL DEFAULT 0.00,
  `grand_total` float(10,2) NOT NULL DEFAULT 0.00,
  `paid_amount` float(10,2) NOT NULL DEFAULT 0.00,
  `due_amount` float(10,2) NOT NULL DEFAULT 0.00,
  `extra_amount` float(10,2) NOT NULL DEFAULT 0.00,
  `order_delivery_By` int(11) DEFAULT NULL,
  `coupon_id` int(11) DEFAULT NULL,
  `search_key` varchar(450) DEFAULT NULL,
  `note` text DEFAULT NULL,
  `pending_at` timestamp NULL DEFAULT NULL,
  `pending_by` int(11) DEFAULT NULL,
  `confirmed_at` timestamp NULL DEFAULT NULL,
  `confirmed_by` int(11) DEFAULT NULL,
  `confirmed_msg` text DEFAULT NULL,
  `shipped_at` timestamp NULL DEFAULT NULL,
  `shipped_by` int(11) DEFAULT NULL,
  `shipped_msg` text DEFAULT NULL,
  `delivered_at` timestamp NULL DEFAULT NULL,
  `delivered_by` int(11) DEFAULT NULL,
  `delivered_msg` text DEFAULT NULL,
  `cancelled_at` timestamp NULL DEFAULT NULL,
  `cancelled_by` int(11) DEFAULT NULL,
  `cancel_reason` varchar(100) DEFAULT NULL,
  `cancel_msg` text DEFAULT NULL,
  `return_at` timestamp NULL DEFAULT NULL,
  `return_by` int(11) DEFAULT NULL,
  `return_msg` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1428 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
